export default isNonInteractiveElement;
/**
 * Returns boolean indicating whether the given element is a non-interactive
 * element. If the element has either a non-interactive role assigned or it is
 * an element with an inherently non-interactive role, then this utility returns
 * true. Elements that lack either an explicitly assigned role or an inherent
 * role are not considered. For those, this utility returns false because a
 * positive determination of interactiveness cannot be determined.
 */
declare function isNonInteractiveElement(tagName: any, attributes: any): boolean;
